<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>FRS <?= esc($profile['nim']) ?></title><link href="<?= base_url('assets/css/bootstrap.min.css') ?>" rel="stylesheet"><link href="<?= base_url('assets/css/siakad.css') ?>" rel="stylesheet"></head><body class="print-page"><main class="container print-sheet"><div class="d-flex justify-content-between align-items-start mb-4"><div><div class="eyebrow">Dokumen akademik</div><h1>Formulir Rencana Studi</h1><p class="mb-0"><?= esc($semester) ?> · Tahun ajaran <?= esc($year) ?></p></div><button class="btn btn-primary no-print" onclick="window.print()">Cetak</button></div><div class="print-profile"><div><span>Nama</span><strong><?= esc($profile['name']) ?></strong></div><div><span>NIM</span><strong><?= esc($profile['nim']) ?></strong></div><div><span>Program studi</span><strong><?= esc($profile['prodi_name']) ?></strong></div></div><table class="table data-table mt-4"><thead><tr><th>No.</th><th>Kode</th><th>Mata kuliah</th><th>Kelas</th><th>Dosen</th><th>SKS</th></tr></thead><tbody><?php $total = 0; foreach ($rows as $i => $row): $total += (int) $row['sks']; ?><tr><td><?= $i + 1 ?></td><td><?= esc($row['kode']) ?></td><td><?= esc($row['mata_kuliah']) ?></td><td><?= esc($row['nama_kelas']) ?></td><td><?= esc($row['dosen_name']) ?></td><td><?= (int) $row['sks'] ?></td></tr><?php endforeach ?><tr><th colspan="5" class="text-end">Total SKS</th><th><?= $total ?></th></tr></tbody></table><div class="signature-row"><div>Mahasiswa<br><br><br><strong><?= esc($profile['name']) ?></strong><br><?= esc($profile['nim']) ?></div><div>Dosen wali<br><br><br><strong><?= esc($profile['dosen_wali'] ?? '____________________') ?></strong></div></div></main></body></html>
